// Lossless Float32 LTC lookup tables copied from Three.js RectAreaLightTexturesLib
// already bundled in Rebot_Arm_AGV/assets/index-BXF1-FJz.js (Hi.init / Uu.init).
// Three.js is MIT licensed. The table data is encoded solely to keep this local
// addon smaller than the original decimal arrays; no light fit is synthesized.
const TABLES = [
  "",
  ""
];
const cache = new WeakMap();

export function initAreaLightTextures(THREE) {
  if (cache.has(THREE.UniformsLib)) return cache.get(THREE.UniformsLib);
  const textures = {};
  TABLES.forEach((encoded, index) => {
    const bytes = Uint8Array.from(atob(encoded), character => character.charCodeAt(0));
    const floats = new Float32Array(bytes.buffer);
    const half = Uint16Array.from(floats, value => THREE.DataUtils.toHalfFloat(value));
    for (const [name, values, type] of [['FLOAT', floats, THREE.FloatType], ['HALF', half, THREE.HalfFloatType]]) {
      const texture = new THREE.DataTexture(values, 64, 64, THREE.RGBAFormat, type);
      texture.wrapS = texture.wrapT = THREE.ClampToEdgeWrapping;
      texture.magFilter = texture.minFilter = THREE.LinearFilter;
      texture.generateMipmaps = false; texture.needsUpdate = true;
      const key = `LTC_${name}_${index + 1}`;
      textures[key] = texture; THREE.UniformsLib[key] = texture;
    }
  });
  cache.set(THREE.UniformsLib, textures);
  return textures;
}
